(_SI_GUID_5, 'active', 'live', '_SI_NOWTIME_', NULL, _SI_GUID_1, 'Header', 0, '{"tag":"header","style":{"position":"relative","left":"0px","top":"0px","width":"100%","height":"1000px"}}', '(function(){function init(){var path=(window.location.pathname||"/").replace(/\\/+$/,"")||"/";var isHome=path==="/"||/index\\.php$/i.test(path);document.body.classList.add(isHome?"si-home":"si-subpage");var nodes=document.querySelectorAll("[data-reveal]");if(!nodes.length){return;}nodes.forEach(function(node,index){node.classList.add("si-reveal");node.style.setProperty("--si-delay",(index*70)+"ms");});if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches){nodes.forEach(function(node){node.classList.add("is-visible");});return;}if(!("IntersectionObserver" in window)){nodes.forEach(function(node){node.classList.add("is-visible");});return;}var observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("is-visible");observer.unobserve(entry.target);}});},{threshold:0.18,rootMargin:"0px 0px -8% 0px"});nodes.forEach(function(node){observer.observe(node);});}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",init,{once:true});}else{init();}})();', ':root{color-scheme:dark light;--si-bg:#101827;--si-surface:#162338;--si-panel:rgba(16,24,39,.78);--si-card:rgba(18,30,48,.88);--si-card-strong:rgba(13,21,35,.94);--si-border:rgba(34,199,217,.18);--si-border-strong:rgba(90,56,232,.28);--si-text:#F4F7FB;--si-muted:rgba(244,247,251,.72);--si-soft:#9fb5d4;--si-blue:#1479F2;--si-violet:#5A38E8;--si-cyan:#22C7D9;--si-shadow:0 30px 80px rgba(2,6,23,.35);--si-radius:24px;}@media (prefers-color-scheme:light){:root{--si-bg:#F4F7FB;--si-surface:#ffffff;--si-panel:rgba(255,255,255,.82);--si-card:#ffffff;--si-card-strong:#ffffff;--si-border:rgba(20,121,242,.12);--si-border-strong:rgba(90,56,232,.18);--si-text:#202838;--si-muted:#5b6880;--si-soft:#6f7c92;--si-shadow:0 24px 60px rgba(16,24,39,.12);}}html{scroll-behavior:smooth;}body{margin:0!important;border:0!important;padding:0!important;background:var(--si-bg)!important;color:var(--si-text)!important;font-family:"Trebuchet MS","Segoe UI",sans-serif;min-height:100%;}body *{box-sizing:border-box;}a{color:inherit;}button,input,select,textarea{font:inherit;}#si_colorscheme{display:none;}#si_brand_shell{position:relative;min-height:1000px;overflow:hidden;background:radial-gradient(circle at top right,rgba(34,199,217,.22),transparent 28%),radial-gradient(circle at 18% 18%,rgba(20,121,242,.28),transparent 34%),linear-gradient(135deg,#101827 0%,#162338 42%,#101827 100%);}#si_brand_shell::before{content:"";position:absolute;inset:0;background:linear-gradient(rgba(244,247,251,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(244,247,251,.05) 1px,transparent 1px);background-size:34px 34px;mask-image:linear-gradient(to bottom,rgba(0,0,0,.95),rgba(0,0,0,.25));opacity:.26;pointer-events:none;}#si_brand_shell::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 0%,rgba(16,24,39,.12) 40%,var(--si-bg) 100%);pointer-events:none;}@media (prefers-color-scheme:light){#si_brand_shell{background:radial-gradient(circle at top right,rgba(34,199,217,.16),transparent 28%),radial-gradient(circle at 18% 18%,rgba(20,121,242,.18),transparent 34%),linear-gradient(135deg,#edf3ff 0%,#f4f7fb 58%,#e8efff 100%);}#si_brand_shell::before{background:linear-gradient(rgba(16,24,39,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(16,24,39,.06) 1px,transparent 1px);opacity:.4;}#si_brand_shell::after{background:linear-gradient(180deg,transparent 0%,rgba(244,247,251,.2) 40%,var(--si-bg) 100%);}}#si_brand_inner{position:relative;z-index:1;max-width:1280px;margin:0 auto;padding:30px 24px 120px;}#si_brand_glow{position:absolute;right:-120px;top:90px;width:420px;height:420px;border-radius:50%;background:linear-gradient(135deg,rgba(20,121,242,.34),rgba(90,56,232,.18));filter:blur(18px);o