em;} .si_button_primary{background:linear-gradient(135deg,#1479F2 0%,#5A38E8 100%);color:#F4F7FB;box-shadow:0 18px 42px rgba(20,121,242,.34);} .si_button_secondary{background:rgba(244,247,251,.05);border:1px solid rgba(244,247,251,.16);color:var(--si-text);} @media (prefers-color-scheme:light){.si_button_secondary{background:rgba(255,255,255,.82);border-color:rgba(20,121,242,.14);}}#si_stat_row{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:42px;} .si_stat_chip{padding:18px 18px 16px;border:1px solid var(--si-border);border-radius:18px;background:rgba(16,24,39,.24);backdrop-filter:blur(8px);box-shadow:var(--si-shadow);} @media (prefers-color-scheme:light){.si_stat_chip{background:rgba(255,255,255,.72);}} .si_stat_chip strong{display:block;margin-bottom:8px;font-size:1rem;} .si_stat_chip span{display:block;color:var(--si-soft);font-size:.94rem;line-height:1.55;}#si_shared_nav{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;max-width:1080px;margin:0 auto;padding:8px 20px 34px;}body.si-home #si_shared_nav{display:none;}body.si-subpage .si_home_only{display:none;}#si_product_sections{max-width:1200px;margin:0 auto;padding:0 24px 96px;} .si_section{position:relative;margin-top:32px;padding:34px;border:1px solid var(--si-border);border-radius:28px;background:var(--si-panel);backdrop-filter:blur(14px);box-shadow:var(--si-shadow);overflow:hidden;} .si_section::before{content:"";position:absolute;inset:0;background:linear-gradient(135deg,rgba(20,121,242,.08),transparent 45%,rgba(34,199,217,.08) 100%);pointer-events:none;} .si_section > *{position:relative;z-index:1;} .si_section_intro{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(280px,.85fr);gap:26px;align-items:stretch;} .si_section h2{margin:0 0 14px;font-size:clamp(2rem,4vw,3.2rem);line-height:1;letter-spacing:-.05em;text-transform:uppercase;} .si_section p{margin:0;color:var(--si-muted);font-size:1rem;line-height:1.75;} .si_callout{display:flex;flex-direction:colu