nt(135deg,#1479F2 0%,#5A38E8 100%);color:#F4F7FB;font-weight:800;} .si_step h3{margin:0 0 10px;font-size:1.08rem;} .si_quote_band{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(280px,.9fr);gap:20px;align-items:center;background:linear-gradient(135deg,rgba(20,121,242,.14),rgba(90,56,232,.18));} .si_quote_band blockquote{margin:0;font-size:clamp(1.5rem,3vw,2.2rem);line-height:1.2;letter-spacing:-.03em;} .si_quote_band p{margin-top:18px;} .si_cta_band{display:flex;align-items:center;justify-content:space-between;gap:20px;} .si_cta_copy h2{margin-bottom:12px;} .si_cta_copy p{max-width:52ch;} .si_cta_actions{display:flex;flex-wrap:wrap;gap:12px;} #si_site_footer{background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,.16));padding:0 24px 48px;} .si_footer_inner{max-width:1200px;margin:0 auto;padding:28px 30px;border:1px solid var(--si-border);border-radius:28px;background:var(--si-panel);backdrop-filter:blur(14px);box-shadow:var(--si-shadow);} .si_footer_grid{display:grid;grid-template-columns:minmax(0,1.2fr) repeat(3,minmax(0,.6fr));gap:22px;} .si_footer_brand{display:flex;flex-direction:column;gap:12px;} .si_footer_brand strong{font-size:1.15rem;letter-spacing:.03em;text-transform:uppercase;} .si_footer_brand p,.si_footer_col a,.si_footer_note{color:var(--si-muted);font-size:.94rem;line-height:1.7;} .si_footer_col strong{display:block;margin-bottom:10px;font-size:.88rem;letter-spacing:.16em;text-transform:uppercase;color:var(--si-text);} .si_footer_col a{display:block;text-decoration:none;margin-bottom:8px;} .si_footer_col a:hover{color:var(--si-cyan);} .si_footer_note{margin-top:18px;padding-top:16px;border-top:1px solid var(--si-border);} #si_loginbox,#si_loggedinbox{width:100%;padding:22px 22px 20px;border:1px solid var(--si-border);border-radius:22px;background:rgba(16,24,39,.72);backdrop-filter:blur(14px);box-shadow:var(--si-shadow);} @media (prefers-color-scheme:light){#si_loginbox,#si_loggedinbox{background:rgba(255,255,255,.9);}} #form_login{display:grid;grid-template-columns:1fr;gap:10px;} #form_login h3,#si_loggedinname{margin:0 0 4px;color:var(--si-text)!important;letter-spacing:.14em;text-transform:uppercase;} #form_login span{color:var(--si-soft)!important;font-size:.86rem;letter-spacing:.12em;text-transform:uppercase;} #form_login input[type=email],#form_login input[type=password]{width:100%;min-height:44px;padding:0 14px;border:1px solid var(--si-border);border-radius:14px;background:rgba(244,247,251,.06);color:var(--si-text);} @media (prefers-color-scheme:light){#form_login input[type=email],#form_login input[type=password]{background:rgba(20,121,242,.04);}} #si_login_remember_me{margin-right:10px;} #button_LgnO8ic,#si_logoutbutton{min-height:44px;padding:0 18px;border:0;border-radius:14px;background:linear-gradient(135deg,#1479F2 0%,#5A38E8 100%);color:#F4F7FB!important;font-weight:800;cursor:pointer;} #a_forgot{color:var(--si-cyan)!important;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-left:0!important;} .si_login_row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;} .si-reveal{opacity:0;transform:translateY(32px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--si-delay,0ms);} .si-reveal.is-visible{opacity:1;transform:none;} @media (max-width:1100px){#si_hero{padding-right:0;}#si_stat_row,.si_feature_grid,.si_reason_grid,.si_step_grid,.si_section_intro,.si_quote_band,.si_footer_grid{grid-template-columns:repeat(2,minmax(0,1fr));}.si_footer_grid{grid-template-columns:minmax(0,1fr) repeat(2,minmax(0,1fr));}} @media (max-width:860px){#si_brand_inner{padding:22px 18px 88px;}#si_topbar{align-items:flex-start;flex-direction:column;}#si_brand_nav{justify-content:flex-start;}#si_hero{padding-top:250px;}#si_stat_row,.si_feature_grid,.si_reason_grid,.si_step_grid,.si_section_intro,.si_quote_band,.si_footer_grid,.si_list{grid-template-columns:minmax(0,1fr);}#si_product_sections{padding:0 18px 78px;}.si_section{padding:24px;}.si_cta_band{align-items:flex-start;flex-direction:column;}#si_site_footer{padding:0 18px 36px;}} @media (max-width:640px){#si_hero{padding-top:390px;}#si_hero h1{max-width:none;font-size:clamp(2.4rem,13vw,4rem);}#si_brand_nav a,#si_shared_nav a,.si_button{width:100%;justify-content:center;}#si_stat_row{gap:12px;}} @media (prefers-reduced-motion:reduce){html{scroll-behavior:auto;}.si-reveal,.si-reveal.is-visible{opacity:1;transform:none;transition:none;}#si_brand_nav a,#si_shared_nav a,.si_button{transition:none;}}', '<div id="si_brand_shell"><div id="si_brand_glow"></div><div id="si_brand_glow_two"></div><div id="si_brand_inner"><div id="si_topbar" data-reveal><a id="si_brand_mark" href="/"><img id="img_mainlogo" src="media/images/logo.png" alt="SuperIntuitive"></a><nav id="si_brand_nav"><a href="/">Overview</a><a href="/about">Story</a><a href="/documentation">Documentation</a><a href="/contact">Contact</a></nav></div><div id="si_hero" data-reveal><p class="si_eyebrow">Downloadable website platform</p><h1>Build the site you want without fighting the tool.</h1><p class="si_lead">SuperIntuitive gives teams a faster way to shape pages, structure content, and refine design with visual control that still respects how real websites are built.</p><div id="si_hero_actions"><a class="si_button si_button_primary" href="/#si_product_sections">Explore features</a><a class="si_button si_button_secondary" href="/documentation">Read documentation</a></div><div id="si_stat_row"><div class="si_stat_chip"><strong>Visual editing</strong><span>Work directly on the page instead of bouncing between disconnected tools.</span></div><div class="si_stat_chip"><strong>Block based delivery</strong><span>Shape sections with structure that can be refined and deployed with intention.</span></div><div class="si_stat_chip"><strong>Built for control</strong><span>Keep the speed of visual work without giving up the details that matter.</span></div></div></div></div></div>', '0000-00-00 00:00:00'),
(_SI_GUID_6, 'active', 'dev', '_SI_NOWTIME_', NULL, _SI_GUID_1, 'Menu', 0, '{"tag":"div","style":{"position":"relative","left":"0px","top":"0px","width":"100%","height":"auto"}}', 'console.log("Menu Script Load Succeeded");', NULL, '<div id="si_shared_nav"><a href="/">Overview</a><a href="/about">Story</a><a href="/documentation">Documentation</a><a href="/contact">Contact</a></div><div id="si_product_sections" class="si_home_only"><section class="si_section si_section_intro" data-reveal><div><span class="si_section_label">What it is for</span><h2>Shape pages, content, and design from one working surface.</h2><p>SuperIntuitive is built for people who want to publish faster without being boxed into rigid templates. It gives teams a direct way to assemble pages, manage structure, and tune the details that make a site feel finished.</p><ul class="si_list"><li>Launch marketing sites that look deliberate from day one.</li><li>Organize growing content without losing visual control.</li><li>Build internal portals and documentation spaces with the same toolset.</li><li>Stay close to the page while still working with real web building blocks.</li></ul></div><aside class="si_callout"><strong>Built for teams who want control without ceremony.</strong><span>Use it when you need a downloadable platform that feels approachable up front and capable when the work gets more ambitious.</span></aside></section><section class="si_section" data-reveal><span class="si_section_label">Features</span><h2>Designed to keep momentum high.</h2><div class="si_feature_grid"><article class="si_feature_card"><h3>Direct page editing</h3><p>Work in the layout itself so decisions happen where the page is actually taking shape.</p></article><article class="si_feature_card"><h3>Reusable block structure</h3><p>Break a site into manageable pieces that can be refined, organized, and reused with less friction.</p></article><article class="si_feature_card"><h3>Visual styling tools</h3><p>Tune presentation with guided controls that make it easier to move from rough idea to polished surface.</p></article><article class="si_feature_card"><h3>Page and site controls</h3><p>Manage navigation, page setup, and site structure without jumping across a tangle of disconnected screens.</p></article><article class="si_feature_card"><h3>Media ready workflow</h3><p>Bring images and other assets into the project flow so content production stays close to publishing.</p></article><article class="si_feature_card"><h3>Room to extend</h3><p>Keep moving with visual tools now while leaving space for deeper customization as the project grows.</p></article></div></section><section class="si_section" data-reveal><span class="si_section_label">How it works</span><h2>Move from idea to launch in a clean rhythm.</h2><div class="si_step_grid"><article class="si_step"><span class="si_step_number">1</span><h3>Lay out the structure</h3><p>Start by shaping the page and placing the sections you need so the whole site has a clear backbone.</p></article><article class="si_step"><span class="si_step_number">2</span><h3>Refine the experience</h3><p>Adjust content, styling, and supporting assets until the site feels aligned with the brand and the goal.</p></article><article class="si_step"><span class="si_step_number">3</span><h3>Ship with confidence</h3><p>Roll forward deliberately with a workflow that keeps the editing surface close to the final result.</p></article></div></section><section class="si_section si_quote_band" data-reveal><div><span class="si_section_label">Why SuperIntuitive</span><blockquote>Built for people who want a serious website platform that still feels fast, visual, and human.</blockquote><p>It is a strong fit when the job calls for business polish, practical control, and a workflow that does not ask you to wrestle the tool before you can build with it.</p></div><div class="si_reason_grid"><article class="si_reason_card"><h3>Faster shaping</h3><p>Spend more energy making decisions and less energy navigating layers of abstraction.</p></article><article class="si_reason_card"><h3>Cleaner ownership</h3><p>Keep the structure of the site visible so teams can understand what they are working with.</p></article><article class="si_reason_card"><h3>Better finish</h3><p>Push beyond generic templates and give the final experience more intention and presence.</p></article></div></section><section class="si_section si_cta_band" data-reveal><div class="si_cta_copy"><span class="si_section_label">Get into it</span><h2>See how SuperIntuitive is put together.</h2><p>Explore the documentation, learn the workflow, and start shaping a site with a platform that is built to stay understandable as the work grows.</p></div><div class="si_cta_actions"><a class="si_button si_button_primary" href="/documentation">Open documentation</a><a class="si_button si_button_secondary" href="/contact">Contact us</a></div></section></div>', '0000-00-00 00:00:00', 0, '{"tag":"div","style":{"position":"relative","left":"0px","top":"0px","width":"100%","height":"auto"}}', 'console.log("Menu Script Load Succeeded");', NULL, '<div id="si_shared_nav"><a href="/">Overview</a><a href="/about">Story</a><a href="/documentation">Documentation</a><a href="/contact">Contact</a></div><div id="si_product_sections" class="si_home_only"><section class="si_section si_section_intro" data-reveal><div><span class="si_section_label">What it is for</span><h2>Shape pages, content, and design from one working surface.</h2><p>SuperIntuitive is built for people who want to publish faster without being boxed into rigid templates. It gives teams a direct way to assemble pages, manage structure, and tune the details that make a site feel finished.</p><ul class="si_list"><li>Launch marketing sites that look deliberate from day one.</li><li>Organize growing content without losing visual control.</li><li>Build internal portals and documentation spaces with the same toolset.</li><li>Stay close to the page while still 