CREATE TABLE `emails` (
	`id` binary(16) NOT NULL,
	`status` enum('active','inactive') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT 'active',
	`statusreason` enum('live','test','dev') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT 'dev',
	`createdon` datetime NOT NULL DEFAULT current_timestamp(),
	`modifiedon` datetime DEFAULT NULL ON UPDATE current_timestamp(),
	`entity_id` binary(16) NOT NULL COMMENT 'entity:entities',
	`name` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci DEFAULT NULL,
