CREATE TABLE `entities` (
	`id` binary(16) NOT NULL,
	`status` enum('active','inactive') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
	`createdon` datetime NOT NULL DEFAULT current_timestamp(),
	`modifiedon` datetime DEFAULT NULL ON UPDATE current_timestamp(),
	`domain_id` binary(16) NOT NULL COMMENT 'entity:domains',
	`subdomain_id` binary(16) NOT NULL COMMENT 'entity:subdomains',
	`name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
	`quantity` int(11) DEFAULT NULL,
	`options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ;

